function getKou(Y,M,D){
  const md=M*100+D;
  let idx=SEKKI.length-1; // 年初(1/1〜1/4)は前年の冬至の続き＝末尾
  for(let i=0;i<SEKKI.length;i++){ if(md>=SEKKI[i].m*100+SEKKI[i].d) idx=i; else break; }
  const s=SEKKI[idx];
  let sy=Y; if(idx===SEKKI.length-1 && M===1) sy=Y-1; // 冬至は前年12月始まり
  let daysSince=Math.floor((Date.UTC(Y,M-1,D)-Date.UTC(sy,s.m-1,s.d))/86400000);
  if(daysSince<0) daysSince=0;
  let third=Math.floor(daysSince/5); if(third>2) third=2; // 初候/次候/末候（約5日ずつ）
  const THIRD=['初候','次候','末候'], k=KOU72[idx][third];
  return {name:k[0], yomi:k[1], sekki:s.name, third:THIRD[third]};
}
