function enToday(t,p){
  if(t.stem===p.stem&&t.branch===p.branch)return{lv:3,tag:"運命の人の日",msg:"今日はまさに、運命の相手「"+p.stem+p.branch+"」と同じ気が巡る日。<b>約2か月に一度</b>の特別な日です。出会いや人との縁を大切にすると良い日。気になる人へのひと言にも良いタイミングです。"};
  if(KANGOU[t.stem]===p.stem||SHIGOU[t.branch]===p.branch)return{lv:2,tag:"恋が動く日",msg:"運命の相手と<b>惹かれ合う気</b>が流れる日。出会いや進展のきっかけが生まれやすいので、いつもの行動範囲を少し広げてみると良いかもしれません。"};
  return{lv:1,tag:"準備の日",msg:"今日はおだやかに土台を整える日。良いご縁を引き寄せる準備が、静かに進んでいます。"};
}
function nextEnDay(base,p){for(let k=1;k<=90;k++){const d=new Date(base.getTime()+k*86400000);const t=pillar(d.getFullYear(),d.getMonth()+1,d.getDate());if(enToday(t,p).lv>=2)return{date:d,days:k};}return null;}
function nextUnmei(base,p){for(let k=1;k<=120;k++){const d=new Date(base.getTime()+k*86400000);const t=pillar(d.getFullYear(),d.getMonth()+1,d.getDate());if(t.stem===p.stem&&t.branch===p.branch)return{date:d,days:k};}return null;}
function weather(idx){
  if(idx>=95)return{ic:"☀️",name:"縁・快晴"};
  if(idx>=80)return{ic:"🌤️",name:"縁・晴れ"};
  if(idx>=65)return{ic:"⛅️",name:"晴れ時々くもり"};
  if(idx>=52)return{ic:"☁️",name:"くもり"};
  return{ic:"🌦️",name:"にわか雨のち晴れ"};
}
/* ── 運勢グレード（相対評価：本人の60干支スコア分布から◎/〇/△を決定）──
   カレンダー(mypage/my-tenki-demo)と“完全に同じ式”で、天気・指数もこのグレードから導く＝画面とメールが必ず一致する。 */
var GRADE_BASE={'正官':2,'正財':1.8,'偏財':1.6,'食神':1.4,'印綬':1.0,'比肩':0.6,'偏印':0.2,'傷官':-0.8,'劫財':-1.0,'偏官':-2.0};
// カレンダー凡例と完全一致の“あなた基準”ラベル（画面＝メール共通）
var GRADE_LABEL={'💮':'特別な日','◎':'調子のいい日','〇':'普通の日','△':'無理しない日'};
function dayRawScore(youStem, youBranch, tt, favSet, imiSet){
  var js=juushin(youStem, tt.stem);
  var s=(GRADE_BASE[js]!==undefined?GRADE_BASE[js]:0);
  var de=STEM_GOGYO[tt.stem];
  if(favSet.indexOf(de)>=0)s+=1.2; else if(imiSet.indexOf(de)>=0)s-=1.2;
  if(CLASH.indexOf(branchRel(tt.branch, youBranch))>=0)s-=2.0;
  return s;
}
var _GRADE_TH={};
function gradeThresholds(youStem, youBranch, favSet, imiSet){
  var key=youStem+youBranch+'|'+favSet.join('')+'|'+imiSet.join('');
  if(_GRADE_TH[key])return _GRADE_TH[key];
  var arr=[];
  for(var i=0;i<60;i++){ var d=new Date(2020,0,1+i); arr.push(dayRawScore(youStem,youBranch,pillar(d.getFullYear(),d.getMonth()+1,d.getDate()),favSet,imiSet)); }
  arr.sort(function(a,b){return a-b;});
  var q=function(pp){return arr[Math.min(59,Math.floor(pp*60))];};
  return (_GRADE_TH[key]={maru:q(0.72),tri:q(0.15)});
}
/* 統一グレード（案C：💮はレア＝全員一律／恋の底上げは正直版）
   ・🌈(運命の人)＝無条件💮
   ・💮は「桃花×高得点×非沖」のみに限定（🌸恋チャンス×高得点は◎に留める）→ 💮の人ごとの二極化を解消し全員一律≈5%に
   ・恋の合図(桃花/恋チャンス・非沖)の底上げは「中位以上(下位15%より上)」のみ◎。下位15%は正直に△
   ・上位28%◎・下位15%△ は従来どおり */
function dailyGrade(you, tt, favSet, imiSet, touka, enlv, ymd){
  var th=gradeThresholds(you.stem, you.branch, favSet, imiSet);
  var s=dayRawScore(you.stem, you.branch, tt, favSet, imiSet);
  if(ymd) s+=ymAdjust(ymd.y, ymd.m, ymd.d, favSet, imiSet, STEM_GOGYO[you.stem]);   // 流年・流月の補正（日付を渡した時のみ）
  var sok=(CLASH.indexOf(branchRel(tt.branch, you.branch))>=0);
  var love=(touka||enlv===2);
  var sym;
  if(enlv===3) sym='💮';
  else if(touka && !sok && s>=th.maru) sym='💮';        // 桃花×高得点×非沖のみ💮（レア化）
  else if(s>=th.maru) sym='◎';                           // 上位28%は◎
  else if(love && !sok && s>th.tri) sym='◎';             // 恋の合図(非沖・中位以上)は底上げ◎
  else if(s<=th.tri) sym='△';                            // 下位15%は正直に△
  else sym='〇';
  // 恋の合図日(モテ運/恋チャンス)は、たとえ△でも天気は“くもり”以上に留める（にわか雨まで落とさない）。
  var triIdx = (sok && !love) ? 45 : 55;
  var idx = sym==='💮'?96 : sym==='◎'?84 : sym==='〇'?68 : triIdx;
  return {sym:sym, idx:idx};
}
