const CLASH=['沖'];
// カレンダーの分野印(💰💼🌐🩷📚)を命式で重み付け：その日の十神(=その日の干の五行)が
// 本人にとって「忌」なら、その分野の“良い印”は出さない（本人には消耗日で、出すと誤誘導になるため）。
// favMap は PersonBazi().fav（五行→'喜'/'忌'/'中庸'）。命式が無い(null)ときは true＝従来どおり全部出す（安全側）。
function domainFavOk(favMap, dayStem){
  if(!favMap) return true;
  return favMap[STEM_GOGYO[dayStem]] !== '忌';
}

// 配列から1つ選ぶ（ハッシュ混合）。pseedが毎日+1でも、個数がいくつでも“全要素がまんべんなく”出る。
// 従来の (pseed*k+c)%len は k と len が約数を共有すると一部しか出ない不具合があったため、その置き換え。
function pickIdx(pseed, salt, len){
  if(!len) return 0;
  var h = Math.imul(((pseed >>> 0) ^ Math.imul(salt|0, 0x9E3779B1)) >>> 0, 2654435761) >>> 0;
  h = Math.imul((h ^ (h >>> 15)) >>> 0, 2246822519) >>> 0;   // 2段目のミックスで雪崩効果を強化
  h = (h ^ (h >>> 13)) >>> 0;
  return Math.floor((h / 4294967296) * len);   // 上位ビットで割り当て＝2の冪(16等)でも均一に分散
}
/* pickSeq：個人×項目ごとに固有の“巡回順”を作り、日付(dayn=jdn)で1つずつ進める。
 *  保証：バンク件数(len)日間は同じ値が絶対に出ない（len≥7なら1週間内の重複ゼロ）。
 *  ub=個人だけのシード（日付を含まない）。順序も開始位置も個人ごとに違うので、他人と同じ並びにならない。
 *  決定的（同じ入力→同じ結果）なので、メールとカレンダー・デモ画面の一致もそのまま保たれる。 */
function pickSeq(ub, salt, len, dayn){
  if(!len) return 0;
  if(len===1) return 0;
  var perm=new Array(len), i, j, t;
  for(i=0;i<len;i++) perm[i]=i;
  for(i=len-1;i>0;i--){ j=pickIdx(ub, (salt|0)*97+i, i+1); t=perm[i]; perm[i]=perm[j]; perm[j]=t; }
  var off=pickIdx(ub, (salt|0)*131+7, len);
  return perm[((dayn+off)%len+len)%len];
}
/* pickRand：その日ごとに“独立したランダム風”の値を返す（規則的な巡回にしない）。
 *  方角・ラッキーナンバー・十二運の言い回しなど「明日を予想されたくない」項目に使う。
 *  日付をシードに混ぜてハッシュするので、連日の並びに規則性が出ず、予測されにくい。 */
function pickRand(ub, salt, len, dayn){
  if(!len) return 0;
  var m=(((ub>>>0) ^ Math.imul((dayn|0)+0x85EB, 2654435761)) >>> 0);
  return pickIdx(m, salt, len);
}

