// interests(配列)から主役ドメインを1つ選ぶ（選んだ順で最初にマップした関心。無ければnull）
function pickFocus(interests){
  if(!interests||!interests.length) return null;
  for(var i=0;i<interests.length;i++){ var dom=INTEREST_DOMAIN[interests[i]]; if(dom) return {domain:dom, interest:interests[i]}; }
  return null;
}

